/* =====================================================================
   js/phieu-chi-dinh-noi-soi.js
   Tính năng: PHIẾU CHỈ ĐỊNH NỘI SOI — BV Đa khoa Bình Dương CS2

   - Form điền trực tiếp (không cần đọc file nguồn), điều hướng Tab/Enter
     giữa các ô nhập giống hệt các tool khác trong bộ (đơn thuốc...).
   - Cho phép thêm/xoá dòng chỉ định nội soi (mặc định 1 dòng "Nội soi
     dạ dày thực quản" đúng như mẫu gốc).
   - Bác sĩ ký tên bên dưới: có thể bật/tắt hiển thị và xoá tên đã điền.
   - Nút "IN PHIẾU CHỈ ĐỊNH" -> window.print() render đúng khổ A4, đúng
     bố cục mẫu Word gốc (logo + SỞ Y TẾ + BV ĐK Bình Dương CS2).
   Không cần sửa nhiều index.html — file này tự render vào #noiSoiContent.
   ===================================================================== */
(function () {
  "use strict";

  var ROOT_ID = "noiSoiContent";
  var LS_KEY = "ns_phieunoisoi_settings_v1";

  var root = document.getElementById(ROOT_ID);
  if (!root) return;

  var PAGE_W_MM = 210, PAGE_H_MM = 297;

  var SO_Y_TE = "SỞ Y TẾ THÀNH PHỐ HỒ CHÍ MINH";
  var HOSPITAL_NAME = "BỆNH VIỆN ĐA KHOA BÌNH DƯƠNG - CƠ SỞ 2";

  var LOGO_B64 = 
'data:image/jpeg;base64,'
;

  /* ---------------------------------------------------------------- */
  /* 1. CSS (tiền tố "ns-")                                            */
  /* ---------------------------------------------------------------- */
  var style = document.createElement("style");
  style.textContent = [
    "#nsWrap{max-width:1400px;margin:0 auto;padding:16px;font-family:inherit;color:var(--text,#222);}",
    "#nsWrap h1{font-size:20px;margin:0 0 4px;}",
    "#nsWrap .ns-sub{color:var(--muted,#777);font-size:13px;margin:0 0 16px;}",
    ".ns-grid{display:grid;grid-template-columns:1fr 300px;gap:18px;align-items:start;}",
    ".ns-grid>.ns-panel{order:2;}",
    ".ns-grid>.ns-stage{order:1;}",
    "@media (max-width:980px){.ns-grid{grid-template-columns:1fr;}}",
    ".ns-panel{background:var(--surface,#fff);border:1px solid var(--border,#e2e2e2);border-radius:12px;padding:14px;position:sticky;top:12px;max-height:calc(100vh - 24px);overflow:auto;}",
    ".ns-panel h3{font-size:14px;margin:14px 0 8px;padding-top:10px;border-top:1px dashed var(--border,#ddd);}",
    ".ns-panel h3:first-child{margin-top:0;padding-top:0;border-top:none;}",
    ".ns-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:none;border-radius:8px;padding:10px 14px;font-size:13.5px;cursor:pointer;background:var(--blue,#0066FF);color:#fff;width:100%;margin-top:4px;transition:transform .12s ease,box-shadow .12s ease,background .2s ease;}",
    ".ns-btn:active{transform:scale(.97);}",
    ".ns-btn.secondary{background:var(--surface-2,#eee);color:var(--text,#222);}",
    ".ns-btn.small{width:auto;padding:6px 10px;font-size:12px;margin-top:0;}",
    ".ns-btn.danger{background:linear-gradient(135deg,#ef4444,#dc2626);color:#fff;}",
    ".ns-btn.print{background:linear-gradient(135deg,#0066FF,#0047b3);box-shadow:0 2px 10px rgba(0,102,255,.35);font-size:15px;padding:13px 14px;font-weight:600;}",
    ".ns-hint{font-size:11.5px;color:var(--muted,#888);line-height:1.5;}",
    ".ns-status{font-size:12px;margin-top:8px;min-height:16px;}",
    ".ns-status.ok{color:#1a7a37;}",
    ".ns-row-actions{display:flex;gap:8px;margin-top:10px;}",
    ".ns-row-actions .ns-btn{margin-top:0;}",
    ".ns-switchrow{display:flex;align-items:center;gap:10px;margin:10px 0;font-size:13px;}",
    ".ns-switch{position:relative;display:inline-block;width:38px;height:22px;flex:none;}",
    ".ns-switch input{opacity:0;width:0;height:0;}",
    ".ns-slider{position:absolute;cursor:pointer;inset:0;background:#ccc;border-radius:22px;transition:.2s;}",
    ".ns-slider:before{content:'';position:absolute;width:16px;height:16px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.2s;box-shadow:0 1px 2px rgba(0,0,0,.3);}",
    ".ns-switch input:checked+.ns-slider{background:#16a34a;}",
    ".ns-switch input:checked+.ns-slider:before{transform:translateX(16px);}",
    /* -------- vùng xem trước / bản in -------- */
    ".ns-stage{background:#5a5f66;border-radius:12px;padding:22px;display:flex;justify-content:center;overflow:auto;}",
    ".ns-sheet-outer{background:#fff;box-shadow:0 6px 24px rgba(0,0,0,.35);position:relative;}",
    "#nsSheet{width:" + PAGE_W_MM + "mm;min-height:" + PAGE_H_MM + "mm;background:#fff;position:relative;font-family:'Times New Roman',Times,serif;color:#000;box-sizing:border-box;padding:14mm 16mm;font-size:13.5px;line-height:1.5;}",
    ".ns-hd{display:flex;align-items:flex-start;gap:5mm;margin-bottom:2mm;}",
    ".ns-hd-logo{flex:0 0 auto;width:20mm;height:auto;}",
    ".ns-hd-text{flex:1 1 auto;text-align:center;font-size:12.5px;line-height:1.4;padding-top:1mm;}",
    ".ns-hd-text .ns-soyte{font-weight:400;text-transform:uppercase;}",
    ".ns-hd-text .ns-hospital{font-weight:bold;text-transform:uppercase;}",
    ".ns-hd-spacer{flex:0 0 auto;width:20mm;}",
    ".ns-title{text-align:center;font-weight:bold;font-size:19px;margin:4mm 0 1mm;text-transform:uppercase;}",
    ".ns-tinhtrang{text-align:center;font-style:italic;font-size:13.5px;margin-bottom:4mm;display:flex;align-items:center;justify-content:center;gap:6px;}",
    ".ns-tinhtrang select{font-style:italic;font-family:inherit;font-size:13.5px;border:none;border-bottom:1px dotted #000;background:transparent;text-align:center;color:#000;}",
    ".ns-field-line{margin-bottom:2.6mm;display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px;}",
    ".ns-field-line label{white-space:nowrap;}",
    ".ns-field-line input,.ns-field-line select{font-family:inherit;font-size:13.5px;border:none;border-bottom:1px dotted #000;background:transparent;color:#000;padding:0 2px;}",
    ".ns-inp-name{flex:1 1 260px;min-width:120px;text-transform:uppercase;}",
    ".ns-inp-dob{width:90px;}",
    ".ns-inp-sex{width:80px;}",
    ".ns-inp-addr{flex:1 1 100%;width:100%;}",
    ".ns-inp-diag{flex:1 1 100%;width:100%;}",
    ".ns-table{width:100%;border-collapse:collapse;margin:3mm 0 5mm;font-size:13px;}",
    ".ns-table th,.ns-table td{border:1px solid #000;padding:1.6mm 2mm;vertical-align:middle;}",
    ".ns-table th{font-weight:bold;text-align:center;background:rgba(0,0,0,.03);}",
    ".ns-table td.ns-stt{text-align:center;width:9%;}",
    ".ns-table td.ns-sl{text-align:center;width:14%;}",
    ".ns-table input,.ns-table textarea{width:100%;box-sizing:border-box;border:none;background:transparent;font-family:inherit;font-size:13px;color:#000;resize:vertical;padding:0;text-align:inherit;}",
    ".ns-table td.ns-stt{color:#000;}",
    ".ns-table td.ns-noidung input{text-align:left;}",
    ".ns-table td.ns-sl input{text-align:center;}",
    ".ns-table td.ns-kq textarea{min-height:5mm;}",
    ".ns-rowdel{border:none;background:none;color:#c0392b;cursor:pointer;font-size:13px;margin-left:6px;}",
    ".ns-addrow-wrap{text-align:left;margin:-2mm 0 5mm;}",
    ".ns-addrow-btn{border:1px dashed #999;background:#fafafa;color:#333;font-size:12px;padding:4px 10px;border-radius:6px;cursor:pointer;}",
    ".ns-footer{margin-top:6mm;text-align:right;}",
    ".ns-footer .ns-daterow{font-style:italic;display:flex;justify-content:flex-end;gap:4px;flex-wrap:wrap;}",
    ".ns-footer .ns-daterow input{font-family:inherit;font-style:italic;font-size:13.5px;border:none;border-bottom:1px dotted #000;background:transparent;color:#000;text-align:center;}",
    ".ns-inp-day,.ns-inp-month{width:26px;}",
    ".ns-inp-year{width:46px;}",
    ".ns-footer .ns-bstitle{font-weight:bold;margin-top:1mm;}",
    ".ns-footer .ns-bsname{margin-top:16mm;font-weight:bold;text-align:right;}",
    ".ns-footer .ns-bsname input{font-family:inherit;font-weight:bold;font-size:13.5px;border:none;border-bottom:1px dotted #000;background:transparent;color:#000;text-align:center;text-transform:uppercase;width:220px;}",
    ".ns-bsname-row{display:flex;justify-content:flex-end;align-items:center;gap:6px;}",
    ".ns-bsname-clear{border:none;background:none;color:#c0392b;cursor:pointer;font-size:12px;}",
    "@media print{",
    "  html.ns-printing,html.ns-printing body{height:" + PAGE_H_MM + "mm !important;overflow:hidden !important;margin:0 !important;padding:0 !important;}",
    "  html.ns-printing body *{visibility:hidden !important;}",
    "  html.ns-printing #nsSheet, html.ns-printing #nsSheet *{visibility:visible !important;}",
    "  html.ns-printing .ns-sheet-outer{position:absolute !important;left:0 !important;top:0 !important;box-shadow:none !important;}",
    "  html.ns-printing #nsSheet{position:absolute !important;left:0 !important;top:0 !important;box-shadow:none !important;}",
    "  html.ns-printing .ns-rowdel,html.ns-printing .ns-addrow-wrap,html.ns-printing .ns-bsname-clear{display:none !important;}",
    "  html.ns-printing .ns-field-line input,html.ns-printing .ns-field-line select,",
    "  html.ns-printing .ns-table input,html.ns-printing .ns-table textarea,",
    "  html.ns-printing .ns-footer input,html.ns-printing .ns-tinhtrang select{border-bottom-color:#000 !important;-webkit-print-color-adjust:exact;print-color-adjust:exact;}",
    "}"
  ].join("\n");
  document.head.appendChild(style);

  /* ---------------------------------------------------------------- */
  /* 2. Danh mục gợi ý nội dung nội soi thường dùng                    */
  /* ---------------------------------------------------------------- */
  var NOISOI_SUGGEST = [
    "Nội soi dạ dày thực quản",
    "Nội soi tai mũi họng",
    "Nội soi trực tràng",
    "Nội soi đại tràng",
    "Nội soi thanh quản"
  ];

  var todayD = new Date();

  /* ---------------------------------------------------------------- */
  /* 3. HTML khung — không cần sửa index.html                          */
  /* ---------------------------------------------------------------- */
  root.innerHTML =
    '<div id="nsWrap">' +
      '<h1>🔬 Phiếu chỉ định nội soi</h1>' +
      '<p class="ns-sub">BV Đa khoa Bình Dương CS2 — khổ A4</p>' +
      '<div class="ns-grid">' +
        '<div class="ns-panel">' +
          '<h3>Tuỳ chọn</h3>' +
          '<div class="ns-switchrow">' +
            '<label class="ns-switch"><input type="checkbox" id="nsShowBsName" checked><span class="ns-slider"></span></label>' +
            '<span>Hiển thị tên bác sĩ ký bên dưới</span>' +
          '</div>' +
          '<p class="ns-hint">Nhấn <b>Tab</b> hoặc <b>Enter</b> để chuyển nhanh giữa các ô. Dùng nút "+ Thêm dòng chỉ định" trong phiếu nếu bệnh nhân chỉ định nhiều loại nội soi.</p>' +
          '<div class="ns-row-actions">' +
            '<button class="ns-btn secondary" id="nsResetBtn">↺ Làm mới phiếu</button>' +
          '</div>' +
          '<button class="ns-btn print" id="nsPrintBtn" style="margin-top:14px;">🖨️ IN PHIẾU CHỈ ĐỊNH</button>' +
          '<div class="ns-status" id="nsStatus"></div>' +
        '</div>' +
        '<div class="ns-stage">' +
          '<div class="ns-sheet-outer">' +
            '<div id="nsSheet">' +
              '<div class="ns-hd">' +
                '<img class="ns-hd-logo" src="' + LOGO_B64 + '" alt="logo">' +
                '<div class="ns-hd-text">' +
                  '<div class="ns-soyte">' + SO_Y_TE + '</div>' +
                  '<div class="ns-hospital">' + HOSPITAL_NAME + '</div>' +
                '</div>' +
                '<div class="ns-hd-spacer"></div>' +
              '</div>' +
              '<div class="ns-title">Phiếu chỉ định nội soi</div>' +
              '<div class="ns-tinhtrang">Tình trạng:' +
                '<select id="nsTinhTrang">' +
                  '<option value="Thường" selected>Thường</option>' +
                  '<option value="Cấp cứu">Cấp cứu</option>' +
                '</select>' +
              '</div>' +
              '<div class="ns-field-line">' +
                '<label>Họ và tên:</label>' +
                '<input type="text" id="nsHoTen" class="ns-inp-name" placeholder="NGUYỄN VĂN B">' +
                '<label>Năm sinh:</label>' +
                '<input type="text" id="nsNamSinh" class="ns-inp-dob" placeholder="19xx" inputmode="numeric" maxlength="4">' +
                '<label>Giới tính:</label>' +
                '<select id="nsGioiTinh" class="ns-inp-sex">' +
                  '<option value="" selected></option>' +
                  '<option value="Nam">Nam</option>' +
                  '<option value="Nữ">Nữ</option>' +
                '</select>' +
              '</div>' +
              '<div class="ns-field-line">' +
                '<label>Địa chỉ:</label>' +
                '<input type="text" id="nsDiaChi" class="ns-inp-addr" placeholder="Số nhà, đường, phường/xã, tỉnh/thành...">' +
              '</div>' +
              '<div class="ns-field-line">' +
                '<label>Chẩn đoán:</label>' +
                '<input type="text" id="nsChanDoan" class="ns-inp-diag" placeholder="VD: Viêm dạ dày &amp; tá tràng">' +
              '</div>' +
              '<table class="ns-table" id="nsTable">' +
                '<thead><tr>' +
                  '<th style="width:9%">STT</th>' +
                  '<th>Nội dung</th>' +
                  '<th style="width:14%">SỐ LƯỢNG</th>' +
                  '<th style="width:26%">KẾT QUẢ</th>' +
                '</tr></thead>' +
                '<tbody id="nsTableBody"></tbody>' +
              '</table>' +
              '<div class="ns-addrow-wrap">' +
                '<button class="ns-addrow-btn" id="nsAddRowBtn" type="button">+ Thêm dòng chỉ định</button>' +
              '</div>' +
              '<div class="ns-footer">' +
                '<div class="ns-daterow">' +
                  '<span>Ngày</span>' +
                  '<input type="text" id="nsNgay" class="ns-inp-day" inputmode="numeric" maxlength="2">' +
                  '<span>tháng</span>' +
                  '<input type="text" id="nsThang" class="ns-inp-month" inputmode="numeric" maxlength="2">' +
                  '<span>năm</span>' +
                  '<input type="text" id="nsNam" class="ns-inp-year" inputmode="numeric" maxlength="4">' +
                '</div>' +
                '<div class="ns-bstitle">Bác sĩ điều trị</div>' +
                '<div class="ns-bsname-row" id="nsBsNameRow">' +
                  '<input type="text" id="nsBsName" placeholder="(Ký, ghi rõ họ tên)">' +
                  '<button class="ns-bsname-clear" id="nsBsNameClear" type="button" title="Xoá tên bác sĩ">✕</button>' +
                '</div>' +
              '</div>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';

  /* ---------------------------------------------------------------- */
  /* 4. Quản lý các dòng chỉ định (thêm / xoá)                         */
  /* ---------------------------------------------------------------- */
  var tbody = document.getElementById("nsTableBody");
  var rowSeq = 0;

  function makeRow(noidung, soluong) {
    rowSeq++;
    var tr = document.createElement("tr");
    tr.className = "ns-row";
    tr.innerHTML =
      '<td class="ns-stt"><span class="ns-stt-num"></span></td>' +
      '<td class="ns-noidung">' +
        '<input type="text" class="ns-fld-noidung" list="nsNoiDungList" value="' + (noidung || "") + '">' +
      '</td>' +
      '<td class="ns-sl"><input type="text" class="ns-fld-sl" inputmode="numeric" value="' + (soluong || "01") + '"></td>' +
      '<td class="ns-kq"><textarea class="ns-fld-kq" rows="1"></textarea>' +
        '<button class="ns-rowdel" type="button" title="Xoá dòng">✕</button>' +
      '</td>';
    return tr;
  }

  // datalist gợi ý (không hiển thị khi in vì datalist vốn không in ra)
  var dl = document.createElement("datalist");
  dl.id = "nsNoiDungList";
  NOISOI_SUGGEST.forEach(function (t) {
    var op = document.createElement("option");
    op.value = t;
    dl.appendChild(op);
  });
  root.appendChild(dl);

  function renumberRows() {
    var rows = tbody.querySelectorAll(".ns-row");
    rows.forEach(function (tr, i) {
      tr.querySelector(".ns-stt-num").textContent = (i + 1);
      var delBtn = tr.querySelector(".ns-rowdel");
      delBtn.style.display = rows.length > 1 ? "" : "none";
    });
  }

  function addRow(noidung, soluong) {
    var tr = makeRow(noidung, soluong);
    tbody.appendChild(tr);
    tr.querySelector(".ns-rowdel").addEventListener("click", function () {
      if (tbody.querySelectorAll(".ns-row").length <= 1) return;
      tr.remove();
      renumberRows();
    });
    tr.querySelector(".ns-fld-kq").addEventListener("input", autoGrowTextarea);
    renumberRows();
    return tr;
  }

  function autoGrowTextarea(e) {
    var el = e.target;
    el.style.height = "auto";
    el.style.height = el.scrollHeight + "px";
  }

  document.getElementById("nsAddRowBtn").addEventListener("click", function () {
    addRow("", "01");
  });

  /* ---------------------------------------------------------------- */
  /* 5. Bác sĩ ký tên: bật/tắt + xoá                                    */
  /* ---------------------------------------------------------------- */
  var bsNameRow = document.getElementById("nsBsNameRow");
  var showBsChk = document.getElementById("nsShowBsName");
  showBsChk.addEventListener("change", function () {
    bsNameRow.style.display = showBsChk.checked ? "" : "none";
  });
  document.getElementById("nsBsNameClear").addEventListener("click", function () {
    document.getElementById("nsBsName").value = "";
    document.getElementById("nsBsName").focus();
  });

  /* ---------------------------------------------------------------- */
  /* 6. Giá trị mặc định: ngày tháng năm hôm nay                       */
  /* ---------------------------------------------------------------- */
  function fillDefaults() {
    document.getElementById("nsNgay").value = todayD.getDate();
    document.getElementById("nsThang").value = (todayD.getMonth() + 1);
    document.getElementById("nsNam").value = todayD.getFullYear();
    addRow("Nội soi dạ dày thực quản", "01");
  }

  /* ---------------------------------------------------------------- */
  /* 7. Điều hướng Tab / Enter giữa các ô nhập                          */
  /* ---------------------------------------------------------------- */
  function focusableFields() {
    return Array.prototype.slice.call(
      root.querySelectorAll(
        '#nsSheet input:not([type=hidden]), #nsSheet select, #nsSheet textarea'
      )
    ).filter(function (el) {
      return el.offsetParent !== null; // chỉ lấy field đang hiển thị
    });
  }

  root.addEventListener("keydown", function (e) {
    if (e.key !== "Enter") return;
    var tag = (e.target.tagName || "").toLowerCase();
    if (tag === "textarea" && !e.ctrlKey) return; // cho phép xuống dòng trong ô kết quả
    if (!e.target.closest("#nsSheet")) return;
    e.preventDefault();
    var fields = focusableFields();
    var idx = fields.indexOf(e.target);
    if (idx > -1 && idx < fields.length - 1) {
      fields[idx + 1].focus();
      if (typeof fields[idx + 1].select === "function") fields[idx + 1].select();
    }
  });

  /* ---------------------------------------------------------------- */
  /* 8. In phiếu                                                        */
  /* ---------------------------------------------------------------- */
  function setStatus(msg, cls) {
    var el = document.getElementById("nsStatus");
    el.textContent = msg || "";
    el.className = "ns-status" + (cls ? " " + cls : "");
  }

  function nsBeforePrint() { document.documentElement.classList.add("ns-printing"); }
  function nsAfterPrint() { document.documentElement.classList.remove("ns-printing"); }

  document.getElementById("nsPrintBtn").addEventListener("click", function () {
    if (typeof logUsage === "function") logUsage("phieunoisoi_print");
    nsBeforePrint();
    window.print();
    setTimeout(nsAfterPrint, 1000);
  });
  window.addEventListener("afterprint", nsAfterPrint);

  /* ---------------------------------------------------------------- */
  /* 9. Làm mới phiếu                                                   */
  /* ---------------------------------------------------------------- */
  document.getElementById("nsResetBtn").addEventListener("click", function () {
    if (!confirm("Xoá toàn bộ thông tin đã điền trên phiếu?")) return;
    document.getElementById("nsHoTen").value = "";
    document.getElementById("nsNamSinh").value = "";
    document.getElementById("nsGioiTinh").value = "";
    document.getElementById("nsDiaChi").value = "";
    document.getElementById("nsChanDoan").value = "";
    document.getElementById("nsTinhTrang").value = "Thường";
    document.getElementById("nsBsName").value = "";
    tbody.innerHTML = "";
    fillDefaults();
    setStatus("Đã làm mới phiếu.", "ok");
    setTimeout(function () { setStatus(""); }, 2000);
  });

  /* ---------------------------------------------------------------- */
  /* 10. Khởi động                                                      */
  /* ---------------------------------------------------------------- */
  fillDefaults();
  document.getElementById("nsHoTen").focus();
})();
